--

CREATE TABLE event_projection_worker_t (
    host_id uuid NOT NULL,
    worker_id character varying(255) NOT NULL,
    projection_name character varying(128) NOT NULL,
    consumer_group character varying(255) NOT NULL,
    source_processor character varying(16) NOT NULL,
    source_partition_key character varying(512) NOT NULL,
    control_id uuid,
    observed_epoch bigint DEFAULT 0 NOT NULL,
    acknowledged_epoch bigint DEFAULT 0 NOT NULL,
    state character varying(16) DEFAULT 'RUNNING'::character varying NOT NULL,
    assignment_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    heartbeat_ts timestamp with time zone NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_projection_worker_control_state_ck CHECK ((((state)::text <> ALL ((ARRAY['PAUSING'::character varying, 'PAUSED'::character varying])::text[])) OR (control_id IS NOT NULL))),
    CONSTRAINT event_projection_worker_epoch_ck CHECK (((observed_epoch >= 0) AND (acknowledged_epoch >= 0) AND (acknowledged_epoch <= observed_epoch))),
    CONSTRAINT event_projection_worker_metadata_ck CHECK ((jsonb_typeof(assignment_metadata) = 'object'::text)),
    CONSTRAINT event_projection_worker_processor_ck CHECK (((source_processor)::text = ANY ((ARRAY['DATABASE'::character varying, 'KAFKA'::character varying])::text[]))),
    CONSTRAINT event_projection_worker_state_ck CHECK (((state)::text = ANY ((ARRAY['RUNNING'::character varying, 'PAUSING'::character varying, 'PAUSED'::character varying, 'STOPPED'::character varying])::text[])))
);


--
-- Name: event_repair_event_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE event_repair_event_t (
    host_id uuid NOT NULL,
    repair_id uuid NOT NULL,
    failure_id uuid NOT NULL,
    event_ordinal integer NOT NULL,
    original_event_id character varying(255) NOT NULL,
    original_payload_digest character varying(64) NOT NULL,
    corrected_payload_format character varying(32) NOT NULL,
    corrected_payload_storage character varying(32) NOT NULL,
    corrected_payload_digest character varying(64) NOT NULL,
    corrected_payload_plain bytea,
    corrected_payload_ciphertext bytea,
    corrected_payload_object_uri character varying(2048),
    corrected_payload_object_version character varying(255),
    corrected_payload_key_id character varying(255),
    corrected_payload_wrapped_key bytea,
    corrected_payload_iv bytea,
    corrected_payload_bytes bigint NOT NULL,
    corrected_event_schema_version character varying(64) NOT NULL,
    changed_field_names jsonb NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_repair_event_changed_fields_ck CHECK (event_replay_changed_fields_valid_v2(changed_field_names)),
    CONSTRAINT event_repair_event_digests_ck CHECK ((((original_payload_digest)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_payload_digest)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_payload_digest)::text <> (original_payload_digest)::text))),
    CONSTRAINT event_repair_event_ordinal_ck CHECK ((event_ordinal >= 0)),
    CONSTRAINT event_repair_event_payload_storage_ck CHECK ((((corrected_payload_storage)::text = 'DATABASE_PLAIN'::text) AND (corrected_payload_plain IS NOT NULL) AND (octet_length(corrected_payload_plain) = corrected_payload_bytes) AND (corrected_payload_bytes > 0) AND ((corrected_payload_digest)::text = encode(sha256(corrected_payload_plain), 'hex'::text)) AND (corrected_payload_ciphertext IS NULL) AND (corrected_payload_object_uri IS NULL) AND (corrected_payload_object_version IS NULL) AND (corrected_payload_key_id IS NULL) AND (corrected_payload_wrapped_key IS NULL) AND (corrected_payload_iv IS NULL))),
    CONSTRAINT event_repair_event_schema_ck CHECK ((length(btrim((corrected_event_schema_version)::text)) > 0))
);


--
-- Name: COLUMN event_repair_event_t.corrected_payload_storage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN event_repair_event_t.corrected_payload_storage IS 'R8 supports DATABASE_PLAIN only; encrypted/object columns remain solely for non-destructive upgrade and rollback compatibility';


--
-- Name: COLUMN event_repair_event_t.corrected_payload_plain; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN event_repair_event_t.corrected_payload_plain IS 'Immutable corrected canonical bytes; never exposed by list/query APIs';


--
-- Name: event_repair_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE event_repair_t (
    host_id uuid NOT NULL,
    repair_id uuid NOT NULL,
    failure_id uuid NOT NULL,
    status character varying(32) DEFAULT 'AWAITING_APPROVAL'::character varying NOT NULL,
    reason character varying(2048) NOT NULL,
    policy_registry_version character varying(64) NOT NULL,
    repair_schema_version character varying(64) NOT NULL,
    original_transaction_fingerprint character varying(64) NOT NULL,
    corrected_transaction_fingerprint character varying(64) NOT NULL,
    changed_event_count integer NOT NULL,
    requested_by character varying(255) NOT NULL,
    requested_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    decision_by character varying(255),
    decision_ts timestamp with time zone,
    approved_by character varying(255),
    approved_ts timestamp with time zone,
    applied_by character varying(255),
    applied_ts timestamp with time zone,
    completed_ts timestamp with time zone,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_repair_actor_pairs_ck CHECK ((((decision_by IS NULL) = (decision_ts IS NULL)) AND ((approved_by IS NULL) = (approved_ts IS NULL)) AND ((applied_by IS NULL) = (applied_ts IS NULL)) AND ((decision_by IS NULL) OR ((decision_by)::text <> (requested_by)::text)) AND ((approved_by IS NULL) OR ((approved_by)::text <> (requested_by)::text)))),
    CONSTRAINT event_repair_count_ck CHECK ((changed_event_count > 0)),
    CONSTRAINT event_repair_fingerprints_ck CHECK ((((original_transaction_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_transaction_fingerprint)::text ~ '^[0-9a-f]{64}$'::text) AND ((corrected_transaction_fingerprint)::text <> (original_transaction_fingerprint)::text))),
    CONSTRAINT event_repair_lifecycle_ck CHECK (((((status)::text = 'AWAITING_APPROVAL'::text) AND (decision_by IS NULL) AND (approved_by IS NULL) AND (applied_by IS NULL) AND (completed_ts IS NULL)) OR (((status)::text = 'APPROVED'::text) AND (decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts) AND (applied_by IS NULL) AND (completed_ts IS NULL)) OR (((status)::text = 'APPLIED'::text) AND (decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts) AND (applied_by IS NOT NULL) AND (completed_ts = applied_ts)) OR (((status)::text = 'REJECTED'::text) AND (decision_by IS NOT NULL) AND (approved_by IS NULL) AND (applied_by IS NULL) AND (completed_ts = decision_ts)) OR (((status)::text = 'CANCELLED'::text) AND (applied_by IS NULL) AND (completed_ts IS NOT NULL) AND (((decision_by IS NULL) AND (approved_by IS NULL)) OR ((decision_by IS NOT NULL) AND ((approved_by)::text = (decision_by)::text) AND (approved_ts = decision_ts)))))),
    CONSTRAINT event_repair_reason_ck CHECK ((length(btrim((reason)::text)) > 0)),
    CONSTRAINT event_repair_status_ck CHECK (((status)::text = ANY ((ARRAY['AWAITING_APPROVAL'::character varying, 'APPROVED'::character varying, 'APPLIED'::character varying, 'CANCELLED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT event_repair_times_ck CHECK (((created_ts >= requested_ts) AND (updated_ts >= requested_ts) AND ((decision_ts IS NULL) OR (decision_ts >= requested_ts)) AND ((approved_ts IS NULL) OR (approved_ts >= requested_ts)) AND ((applied_ts IS NULL) OR (applied_ts >= approved_ts)) AND ((completed_ts IS NULL) OR (completed_ts >= requested_ts)))),
    CONSTRAINT event_repair_versions_ck CHECK (((length(btrim((policy_registry_version)::text)) > 0) AND (length(btrim((repair_schema_version)::text)) > 0)))
);


--
-- Name: event_replay_action_request_t; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE event_replay_action_request_t (
    host_id uuid NOT NULL,
    action_request_id uuid NOT NULL,
    action_type character varying(32) NOT NULL,
    status character varying(32) DEFAULT 'AWAITING_APPROVAL'::character varying NOT NULL,
    target_ids jsonb NOT NULL,
    expected_state jsonb NOT NULL,
