    completed_ts timestamp with time zone,
    expires_ts timestamp with time zone NOT NULL,
    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_replay_action_request_approval_ck CHECK ((((approved_by IS NULL) = (approved_ts IS NULL)) AND (((status)::text <> 'COMPLETED'::text) OR ((approved_ts IS NOT NULL) AND (completed_ts IS NOT NULL))))),
    CONSTRAINT event_replay_action_request_expiry_ck CHECK ((expires_ts > requested_ts)),
    CONSTRAINT event_replay_action_request_json_ck CHECK (((jsonb_typeof(target_ids) = 'array'::text) AND (jsonb_array_length(target_ids) > 0) AND (jsonb_typeof(expected_state) = 'object'::text))),
    CONSTRAINT event_replay_action_request_reason_ck CHECK ((length(btrim((reason)::text)) > 0)),
    CONSTRAINT event_replay_action_request_status_ck CHECK (((status)::text = ANY ((ARRAY['AWAITING_APPROVAL'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT event_replay_action_request_type_ck CHECK (((action_type)::text = ANY ((ARRAY['WAIVE_FAILURES'::character varying, 'RELEASE_WITH_GAP'::character varying])::text[])))
);


