    created_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT event_replay_attempt_metadata_ck CHECK (((jsonb_typeof(pre_projection_metadata) = 'object'::text) AND (jsonb_typeof(post_projection_metadata) = 'object'::text))),
    CONSTRAINT event_replay_attempt_number_ck CHECK (((attempt_number > 0) AND (fencing_token >= 0))),
    CONSTRAINT event_replay_attempt_result_ck CHECK (((result)::text = ANY ((ARRAY['RUNNING'::character varying, 'SUCCEEDED'::character varying, 'FAILED'::character varying, 'ABANDONED'::character varying])::text[]))),
    CONSTRAINT event_replay_attempt_terminal_ck CHECK (((((result)::text = 'RUNNING'::text) AND (completed_ts IS NULL) AND (projection_committed = false)) OR (((result)::text <> 'RUNNING'::text) AND (completed_ts IS NOT NULL))))
);


