    CONSTRAINT llm_public_alias_embedding_space_ck CHECK ((((operations ? 'embed'::text) AND ((jsonb_typeof((required_capabilities -> 'embeddingSpace'::text)) = 'object'::text) AND ((length(((required_capabilities -> 'embeddingSpace'::text) ->> 'spaceId'::text)) >= 1) AND (length(((required_capabilities -> 'embeddingSpace'::text) ->> 'spaceId'::text)) <= 255)) AND (((required_capabilities -> 'embeddingSpace'::text) ->> 'revision'::text) ~ '^[1-9][0-9]*$'::text) AND (((required_capabilities -> 'embeddingSpace'::text) ->> 'dimension'::text) ~ '^[1-9][0-9]*$'::text) AND (((required_capabilities -> 'embeddingSpace'::text) ->> 'normalization'::text) = ANY (ARRAY['none'::text, 'l2'::text])) AND (((required_capabilities -> 'embeddingSpace'::text) ->> 'distanceMetric'::text) = ANY (ARRAY['cosine'::text, 'inner_product'::text, 'l2'::text])) AND ((length(((required_capabilities -> 'embeddingSpace'::text) ->> 'documentInputTransformVersion'::text)) >= 1) AND (length(((required_capabilities -> 'embeddingSpace'::text) ->> 'documentInputTransformVersion'::text)) <= 255)) AND (((required_capabilities -> 'embeddingSpace'::text) - ARRAY['spaceId'::text, 'revision'::text, 'dimension'::text, 'normalization'::text, 'distanceMetric'::text, 'documentInputTransformVersion'::text]) = '{}'::jsonb))) OR ((NOT (operations ? 'embed'::text)) AND (NOT (required_capabilities ? 'embeddingSpace'::text))))),
    CONSTRAINT llm_public_alias_embedding_workload_lane_ck CHECK (((embedding_workload_lane)::text = ANY ((ARRAY['standard'::character varying, 'kb_query'::character varying, 'kb_index'::character varying])::text[]))),
    CONSTRAINT llm_public_alias_expected_space_required_ck CHECK (((NOT require_expected_embedding_space) OR (operations ? 'embed'::text))),
    CONSTRAINT llm_public_alias_t_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT llm_public_alias_t_check CHECK (((replacement_alias_id IS NULL) OR (replacement_alias_id <> public_alias_id))),
    CONSTRAINT llm_public_alias_t_logging_mode_check CHECK (((logging_mode)::text = ANY ((ARRAY['NONE'::character varying, 'METADATA'::character varying, 'REDACTED'::character varying])::text[]))),
    CONSTRAINT llm_public_alias_t_max_input_tokens_check CHECK (((max_input_tokens IS NULL) OR (max_input_tokens > 0))),
    CONSTRAINT llm_public_alias_t_max_output_tokens_check CHECK (((max_output_tokens IS NULL) OR (max_output_tokens > 0))),
    CONSTRAINT llm_public_alias_t_max_request_bytes_check CHECK (((max_request_bytes IS NULL) OR (max_request_bytes > 0))),
    CONSTRAINT llm_public_alias_t_operations_check CHECK (((jsonb_typeof(operations) = 'array'::text) AND (jsonb_array_length(operations) > 0) AND (operations <@ '["generate", "embed"]'::jsonb))),
    CONSTRAINT llm_public_alias_t_pii_mode_check CHECK (((pii_mode)::text = ANY ((ARRAY['DENY'::character varying, 'REDACT'::character varying, 'TOKENIZE'::character varying, 'ALLOW'::character varying])::text[]))),
    CONSTRAINT llm_public_alias_t_required_capabilities_check CHECK ((jsonb_typeof(required_capabilities) = 'object'::text)),
    CONSTRAINT llm_public_alias_visibility_ck CHECK (((((alias_visibility)::text = 'PUBLIC'::text) AND (bound_agent_def_id IS NULL) AND (bound_workload_principal IS NULL)) OR (((alias_visibility)::text = 'INTERNAL_LEGACY'::text) AND (bound_agent_def_id IS NOT NULL) AND (bound_workload_principal IS NULL)) OR (((alias_visibility)::text = 'INTERNAL_WORKLOAD'::text) AND (bound_agent_def_id IS NULL) AND ((length((bound_workload_principal)::text) >= 1) AND (length((bound_workload_principal)::text) <= 255)))))
);


--
-- Name: knowledge_qualified_embedding_alias_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW knowledge_qualified_embedding_alias_v AS
 SELECT alias.host_id,
    alias.host_id AS alias_owner_host_id,
    alias.public_alias_id,
    alias.alias_name,
    (alias.required_capabilities -> 'embeddingSpace'::text) AS embedding_space,
    true AS active,
    alias.update_ts,
    count(*) AS eligible_route_count
   FROM ((((llm_public_alias_t alias
     JOIN llm_alias_route_t route ON (((route.host_id = alias.host_id) AND (route.public_alias_id = alias.public_alias_id) AND (route.active IS TRUE))))
     JOIN llm_provider_deployment_t deployment ON (((deployment.host_id = route.host_id) AND (deployment.provider_deployment_id = route.provider_deployment_id) AND (deployment.active IS TRUE) AND ((deployment.provider_protocol)::text = 'openai_embeddings'::text))))
     JOIN llm_model_registration_t registration ON (((registration.host_id = deployment.host_id) AND (registration.model_registration_id = deployment.model_registration_id) AND (registration.active IS TRUE))))
     JOIN llm_model_t model ON (((model.model_id = registration.model_id) AND (model.active IS TRUE))))
  WHERE ((alias.active IS TRUE) AND (alias.operations ? 'embed'::text) AND (alias.require_expected_embedding_space IS TRUE) AND ((((model.declared_capabilities || registration.capability_restrictions) -> 'embedding'::text) -> 'space'::text) = (alias.required_capabilities -> 'embeddingSpace'::text)))
  GROUP BY alias.host_id, alias.public_alias_id, alias.alias_name, (alias.required_capabilities -> 'embeddingSpace'::text), alias.update_ts
 HAVING bool_and(((jsonb_array_length(COALESCE((((model.declared_capabilities || registration.capability_restrictions) -> 'embedding'::text) -> 'supportedDimensions'::text), (((model.declared_capabilities || registration.capability_restrictions) -> 'embedding'::text) -> 'dimensions'::text))) = 1) AND (COALESCE((((model.declared_capabilities || registration.capability_restrictions) -> 'embedding'::text) -> 'supportedDimensions'::text), (((model.declared_capabilities || registration.capability_restrictions) -> 'embedding'::text) -> 'dimensions'::text)) @> jsonb_build_array((((alias.required_capabilities -> 'embeddingSpace'::text) ->> 'dimension'::text))::integer))));


--
-- Name: knowledge_embedding_profile_runtime_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW knowledge_embedding_profile_runtime_v WITH (security_barrier='true') AS
 SELECT profile.profile_id,
    profile.profile_revision,
    profile.expected_space_id,
    profile.expected_space_revision,
    profile.dimension,
    profile.document_input_transform_version,
    profile.query_input_transform_version,
    alias.alias_name
   FROM (knowledge_embedding_profile_t profile
     JOIN knowledge_qualified_embedding_alias_v alias ON (((alias.alias_owner_host_id = profile.alias_owner_host_id) AND (alias.public_alias_id = profile.public_alias_id) AND ((alias.embedding_space ->> 'spaceId'::text) = (profile.expected_space_id)::text) AND (((alias.embedding_space ->> 'revision'::text))::bigint = profile.expected_space_revision) AND (((alias.embedding_space ->> 'dimension'::text))::integer = profile.dimension) AND ((alias.embedding_space ->> 'documentInputTransformVersion'::text) = (profile.document_input_transform_version)::text))))
  WHERE (profile.active = true);


