    aggregate_version bigint DEFAULT 1 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    update_ts timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    update_user character varying(126) DEFAULT SESSION_USER NOT NULL,
    CONSTRAINT llm_provider_endpoint_auth_ck CHECK ((((endpoint_auth_mode)::text = ANY ((ARRAY['NONE'::character varying, 'BEARER'::character varying, 'API_KEY'::character varying, 'BEDROCK_API_KEY'::character varying, 'AWS_SIGV4'::character varying])::text[])) AND (((endpoint_auth_mode)::text = 'API_KEY'::text) = (api_key_header IS NOT NULL)) AND ((api_key_header IS NULL) OR ((api_key_header)::text = ANY ((ARRAY['authorization'::character varying, 'x-api-key'::character varying])::text[]))))),
    CONSTRAINT llm_provider_endpoint_bedrock_ck CHECK (((((provider_type)::text = 'aws_bedrock'::text) = ((provider_protocol)::text = 'bedrock_converse'::text)) AND ((((provider_type)::text = 'aws_bedrock'::text) AND ((aws_region)::text ~ '^[a-z0-9]+(-[a-z0-9]+)+-[0-9]+$'::text) AND ((endpoint_auth_mode)::text = ANY ((ARRAY['BEDROCK_API_KEY'::character varying, 'AWS_SIGV4'::character varying])::text[]))) OR (((provider_type)::text <> 'aws_bedrock'::text) AND (aws_region IS NULL) AND ((endpoint_auth_mode)::text <> ALL ((ARRAY['BEDROCK_API_KEY'::character varying, 'AWS_SIGV4'::character varying])::text[])))))),
    CONSTRAINT llm_provider_endpoint_pool_ck CHECK (((pool_idle_timeout_ms > 0) AND (client_refresh_interval_ms >= pool_idle_timeout_ms))),
    CONSTRAINT llm_provider_endpoint_profile_ck CHECK ((((network_profile_mode)::text = ANY ((ARRAY['PUBLIC_TLS'::character varying, 'PRIVATE_TLS'::character varying, 'PRIVATE_PLAINTEXT'::character varying])::text[])) AND ((network_termination)::text = ANY ((ARRAY['NATIVE'::character varying, 'LIGHT_GATEWAY_SIDECAR'::character varying])::text[])) AND ((((network_profile_mode)::text = 'PUBLIC_TLS'::text) AND (base_url ~ '^https://'::text) AND (network_zone_id IS NULL)) OR (((network_profile_mode)::text = 'PRIVATE_TLS'::text) AND (base_url ~ '^https://'::text) AND (network_zone_id IS NOT NULL)) OR (((network_profile_mode)::text = 'PRIVATE_PLAINTEXT'::text) AND (base_url ~ '^http://'::text) AND (network_zone_id IS NOT NULL) AND ((endpoint_auth_mode)::text = 'NONE'::text))))),
    CONSTRAINT llm_provider_endpoint_protocol_ck CHECK (((provider_protocol)::text = ANY ((ARRAY['openai_chat'::character varying, 'openai_responses'::character varying, 'openai_embeddings'::character varying, 'anthropic_messages'::character varying, 'bedrock_converse'::character varying])::text[]))),
    CONSTRAINT llm_provider_endpoint_t_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT llm_provider_endpoint_t_headers_check CHECK ((jsonb_typeof(headers) = 'object'::text)),
    CONSTRAINT llm_provider_endpoint_trust_ck CHECK (((((network_profile_mode)::text = 'PRIVATE_TLS'::text) = ((trust_bundle_reference IS NOT NULL) AND (trust_bundle_sha256 IS NOT NULL))) AND ((trust_bundle_sha256 IS NULL) OR ((trust_bundle_sha256)::text ~ '^[0-9a-f]{64}$'::text))))
);


